head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst30500";
scwin.hCoumn1 = null;
scwin.hCoumn2 = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.hCoumn1 = $c.util.getComponent('hCoumn1');
        scwin.hCoumn2 = $c.util.getComponent('hCoumn2');
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst30500.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchFromDate", fn: function () { return String(String((dma_pageContext.get("searchFromDate") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnInit();
        scwin.hCoumn1.setStyle("display", "");
        scwin.hCoumn2.setStyle("display", "none");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnFindCorpName2_onclick
 * @description btn_fnFindCorpName2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName2_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnFindCorpName2_onclick' }); }
};

/**
 * @method
 * @name btn_findEtsIsu_onclick
 * @description btn_findEtsIsu 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findEtsIsu_onclick = function(e){
    try {
        findEtsIsu();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst30500.btn_findEtsIsu_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpName_onclick
 * @description btn_fnSearchCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnDownload_onclick' }); }
};

/**
 * @method
 * @name btn_fnViewTab_onclick
 * @description btn_fnViewTab 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnViewTab_onclick = async function(e){
    try {
        await scwin.fnViewTab(0)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnViewTab_onclick' }); }
};

/**
 * @method
 * @name btn_fnViewTab_2_onclick
 * @description btn_fnViewTab_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnViewTab_2_onclick = async function(e){
    try {
        await scwin.fnViewTab(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnViewTab_2_onclick' }); }
};

/**
 * @method
 * @name btn_fnViewTab_3_onclick
 * @description btn_fnViewTab_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnViewTab_3_onclick = async function(e){
    try {
        await scwin.fnViewTab(2)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnViewTab_3_onclick' }); }
};

/**
 * @method
 * @name btn_fnViewTab_4_onclick
 * @description btn_fnViewTab_4 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnViewTab_4_onclick = async function(e){
    try {
        await scwin.fnViewTab(3)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnViewTab_4_onclick' }); }
};

/**
 * @method
 * @name btn_fnViewTab_5_onclick
 * @description btn_fnViewTab_5 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnViewTab_5_onclick = async function(e){
    try {
        await scwin.fnViewTab(4)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst30500.btn_fnViewTab_5_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/investwarn/investattentwarnrisky.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/investwarn/investattentwarnrisky.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod( "-1 ') */
    if (($c.util.getComponent('ipt_searchFromDate').getValue() === null ? '' : String($c.util.getComponent('ipt_searchFromDate').getValue())) !== '') {
        $c.util.getComponent('cal_startDate').setValue(($c.util.getComponent("ipt_searchFromDate").getValue() || ''));
        $c.util.getComponent('cal_endDate').setValue(($c.util.getComponent("ipt_searchFromDate").getValue() || ''));
    }
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    const valMenuIdx = ($c.util.getComponent("dma_fnDownloadReq").get("menuIndex") || '');
    if (valMenuIdx === '2' || valMenuIdx === '3') {
        await scwin.fnOrder("3", "D");
    } else {
        await scwin.fnOrder("4", "D");
    }
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnViewTab
 * @description fn View Tab 처리
 * @param {*} tabDiv tabDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnViewTab = async function (tabDiv) {
    $(document).find("li[id=menuType]").each(function(index) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (index === tabDiv) {
                $(this).addClass("active");
            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("menuIndex", tabDiv + 1);
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    if (($c.util.getComponent('AKCKwd').getValue() === null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    await scwin.fnSearchInit();
}
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (ipt_repIsuSrtCd) {
    if (ipt_repIsuSrtCd === "") {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        const valSearchCodeType = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (valSearchCodeType === "number") {
            await $c.win.alert("조회한 종목명이 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
        await scwin.fnSearchInit();
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_startDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_endDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_startDate').getValue(), $c.util.getComponent('cal_endDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.date.addYear($c.util.getComponent('cal_startDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_endDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    const valMenuIdx = ($c.util.getComponent("dma_fnDownloadReq").get("menuIndex") || '');
    const radioArr = $(document).find("input:radio[name=rd_marketType]");
    scwin.hCoumn1.setStyle("display", "");
    scwin.hCoumn2.setStyle("display", "none");
    if (valMenuIdx === '1') {
        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisu_sub");
    } else {
        if (valMenuIdx === '2') {
            $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstwarnisu_sub");
        } else {
            if (valMenuIdx === '3') {
                $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstriskisu_sub");
            } else {
                if (valMenuIdx === '4') {
                    $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuelw_sub");
                } else {
                    if (valMenuIdx === '5') {
                        scwin.hCoumn1.setStyle("display", "none");
                        scwin.hCoumn2.setStyle("display", "");
                        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuets_sub");
                    } else {
                        return;
                    }
                }
            }
        }
    }
    if (valMenuIdx === '5') {
        radioArr[4].checked = true;
    } else {
        if (valMenuIdx !== '5' && radioArr[4].checked) {
            radioArr[0].checked = true;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() !== null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "investattentwarnriskySub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_startDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_endDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_startDate').getValue(), $c.util.getComponent('cal_endDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.date.addYear($c.util.getComponent('cal_startDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_endDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    const valMenuIdx = ($c.util.getComponent("dma_fnDownloadReq").get("menuIndex") || '');
    if (valMenuIdx === '1') {
        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisu_down");
    } else {
        if (valMenuIdx === '2') {
            $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstwarnisu_down");
        } else {
            if (valMenuIdx === '3') {
                $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstriskisu_down");
            } else {
                if (valMenuIdx === '4') {
                    $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuelw_down");
                } else {
                    if (valMenuIdx === '5') {
                        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuets_down");
                    } else {
                        return;
                    }
                }
            }
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "investattentwarnriskySub");
    await scwin.tx_fnDownload();
};

